using System;using System.Linq;using System.Xml;using System.Xml.Linq;
static class Program{
static int checks;static void Check(bool b,string name){if(!b)throw new Exception(name);checks++;}
static string payload="AQ==",hash=RebirthNpcNativeReconstruction.Digest(new byte[]{1});
