static XElement Valid(){return new XElement("nativeReconstruction",new XAttribute("version",1),new XAttribute("required",1),new XAttribute("nativeVersion",38),new XAttribute("owner",owner),new XAttribute("profile","specialist.medic"),new XAttribute("generation",1),new XAttribute("inventoryRevision",3),new XAttribute("assembly",new string('a',64)),new XAttribute("complete",1),new[]{"actor","bodyDamage","stats","buffs","toolbelt","equipment","bag"}.Select(n=>new XElement(n,new XAttribute("payload",payload),new XAttribute("sha256",hash))),new XElement("slots",Slot()),new XElement("controllers"));}
