foreach(var name in new[]{"actor","bodyDamage","stats","buffs","toolbelt","equipment","bag"}){var n=Valid();n.Element(name).SetAttributeValue("sha256",new string('b',64));Check(!RebirthNpcNativeReconstruction.TryRead(n,out _),"hash"+name);}
