var stackNode=new XElement("nativeStack",new XAttribute("version",1),new XAttribute("id",stackId.ToString("N")),new XAttribute("owner",owner),new XAttribute("item","fixture"),new XAttribute("count",2),new XAttribute("payload",payload));Check(RebirthNpcNativeStackRecord.TryRead(stackNode,out var record),"actual stack codec");Check(RebirthNpcNativeStackSet.TryCreate(owner,3,new[]{record},out var set),"actual custody codec");Check(d.TryValidateCustody(set),"exact custody");Check(!d.TryValidateCustody(set.WithRevision(4)),"wrong revision");Check(!d.TryValidateCustody(null),"missing custody");
var xml=new XmlDocument();xml.LoadXml("<npc/>");Check(RebirthNpcNativeReconstruction.TryReadAggregate(xml.DocumentElement,out var missing)&&missing==null,"legacy missing");xml.DocumentElement.AppendChild(d.WriteAggregate(xml));Check(RebirthNpcNativeReconstruction.TryReadAggregate(xml.DocumentElement,out var saved)&&saved.Owner==d.Owner,"aggregate helper roundtrip");xml.DocumentElement.AppendChild(d.WriteAggregate(xml));Check(!RebirthNpcNativeReconstruction.TryReadAggregate(xml.DocumentElement,out _),"duplicate aggregate");
Check(d.TryValidateControllers(null,null),"empty controller set");
var withController=Valid();withController.Element("controllers").Add(new XElement("fragment",new XAttribute("type","fixture.controller"),new XAttribute("version",1),new XAttribute("required",1),new XAttribute("payload",payload),new XAttribute("sha256",hash)));Check(RebirthNpcNativeReconstruction.TryRead(withController,out var controllerState),"controller codec");
var fragmentSet=new RebirthNpcControllerFragmentSet{FragmentCount=1,Fragments=new[]{new RebirthNpcControllerFragment{ControllerTypeId="fixture.controller",FragmentVersion=1,FragmentLength=1,Bytes=new byte[]{1},FragmentChecksum=hash,Required=true}}};
Check(!controllerState.TryValidateControllers(fragmentSet,null),"required unknown handler fails");Check(controllerState.TryValidateControllers(fragmentSet,(id,v)=>id=="fixture.controller"&&v==1),"exact qualified handler");fragmentSet.Fragments[0].Bytes[0]=2;Check(!controllerState.TryValidateControllers(fragmentSet,(id,v)=>true),"changed controller bytes");
