var actor=new EntityRebirthHumanoidNPC{RebirthRuntimeState=new RebirthNpcRuntimeState{StableId=owner,ProfileId="specialist.medic"}};actor.inventory.ItemGrid.Items[0]=new ItemStack(new ItemValue(),2);GameManager.Instance.World=actor.world;
Check(RebirthNpcNativeReconstructionCapture.TryCapture(actor,person,set,null,out var captured,out _),"actual capture source with native API doubles");Check(captured.TryValidateCustody(set)&&captured.Matches(person),"capture binding");actor.Overflow=true;Check(!RebirthNpcNativeReconstructionCapture.TryCapture(actor,person,set,null,out _,out _),"preallocation bound refusal");actor.Overflow=false;actor.world.Remote=true;Check(!RebirthNpcNativeReconstructionCapture.TryCapture(actor,person,set,null,out _,out _),"client capture refusal");actor.world.Remote=false;actor.Dead=true;Check(!RebirthNpcNativeReconstructionCapture.TryCapture(actor,person,set,null,out _,out _),"dead capture refusal");actor.Dead=false;Check(!RebirthNpcNativeReconstructionCapture.TryCapture(actor,person,null,null,out _,out _),"no custody grant");
actor.world.Actor=actor;GameManager.Instance.World=actor.world;RebirthNpcInventoryTransactionService.Custody=set;RebirthNpcInventoryTransactionService.Revision=3;
Check(RebirthNpcNativeReconstructionCapture.TryCaptureCheckpoint(actor.RebirthRuntimeState,person),"actual checkpoint helper");Check(person.NativeReconstruction!=null&&person.Vitals.CurrentHealth==80,"checkpoint evidence and actual health");RebirthNpcInventoryTransactionService.Custody=null;RebirthNpcInventoryTransactionService.Revision=0;Check(!RebirthNpcNativeReconstructionCapture.TryCaptureCheckpoint(actor.RebirthRuntimeState,person)&&person.NativeReconstruction==null,"changed active evidence invalidated");
