checks+=RigidbodyStateFixture.Run();checks+=BodyPolicyIntegrationFixture.Run();checks+=BodyPolicyFixture.Run();checks+=IdleHandQualificationFixture.Run();checks+=DerivedHandRetirementFixture.Run();checks+=HandMaterializationFixture.Run();checks+=NativeHandFixture.Run();checks+=NativeGeometryFixture.Run();checks+=EventGateDoubles.EventGateFixture.Run();checks+=PhysicalHoldFixture.Run();checks+=NativeHeaderProjectionFixture.Run();checks+=NativeHeaderFixture.Run();checks+=OriginalScopeFixture.Run();checks+=NativePreflightFixture.Run();checks+=HydrationDoubles.HydrationFixture.Run();
